import{_ as e,c as a,o,U as t}from"./chunks/framework.Zwu4-4z4.js";const g=JSON.parse('{"title":"Control Box Digital I/O Dedicated Function v221004","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"technical_docs/digital_io_function.md","filePath":"technical_docs/digital_io_function.md"}'),r={name:"technical_docs/digital_io_function.md"},i=t('<h1 id="control-box-digital-i-o-dedicated-function-v221004" tabindex="-1">Control Box Digital I/O Dedicated Function v221004 <a class="header-anchor" href="#control-box-digital-i-o-dedicated-function-v221004" aria-label="Permalink to &quot;Control Box Digital I/O Dedicated Function v221004&quot;">​</a></h1><h3 id="_1-control-box-digital-input-function-definition" tabindex="-1">1. Control Box Digital Input Function Definition <a class="header-anchor" href="#_1-control-box-digital-input-function-definition" aria-label="Permalink to &quot;1. Control Box Digital Input Function Definition&quot;">​</a></h3><br><h4 id="_1-1-r-start-program-once" tabindex="-1">1.1 R=Start Program (Once) <a class="header-anchor" href="#_1-1-r-start-program-once" aria-label="Permalink to &quot;1.1 R=Start Program (Once)&quot;">​</a></h4><p>Idle: Run the program currently loaded once.<br> Pause: Restart the program.<br> (Rising Edge)</p><h4 id="_1-2-r-stop-program" tabindex="-1">1.2 R=Stop Program <a class="header-anchor" href="#_1-2-r-stop-program" aria-label="Permalink to &quot;1.2 R=Stop Program&quot;">​</a></h4><p>Stops actions and running programs.<br> (Rising Edge)</p><h4 id="_1-3-r-pause-program" tabindex="-1">1.3 R=Pause Program <a class="header-anchor" href="#_1-3-r-pause-program" aria-label="Permalink to &quot;1.3 R=Pause Program&quot;">​</a></h4><p>Pause the running program.<br> (Rising Edge)</p><h4 id="_1-4-r-freedriveon-f-off" tabindex="-1">1.4 R=FreeDriveOn / F=Off <a class="header-anchor" href="#_1-4-r-freedriveon-f-off" aria-label="Permalink to &quot;1.4 R=FreeDriveOn / F=Off&quot;">​</a></h4><p>R=Use direct teaching mode.<br> F=Don’t use direct teaching mode.</p><h4 id="_1-5-r-speed-100-f-0" tabindex="-1">1.5 R=Speed 100% / F=0% <a class="header-anchor" href="#_1-5-r-speed-100-f-0" aria-label="Permalink to &quot;1.5 R=Speed 100% / F=0%&quot;">​</a></h4><p>R=Set the speed bar to 100%.<br> F=Set the speed bar to 0%.</p><h4 id="_1-6-r-real-mode-f-simulation" tabindex="-1">1.6 R=Real mode / F=simulation <a class="header-anchor" href="#_1-6-r-real-mode-f-simulation" aria-label="Permalink to &quot;1.6 R=Real mode / F=simulation&quot;">​</a></h4><p>R=Change to real robot mode.<br> F=Change to simulation mode.</p><h4 id="_1-7-r-initialize-robot" tabindex="-1">1.7 R=Initialize Robot <a class="header-anchor" href="#_1-7-r-initialize-robot" aria-label="Permalink to &quot;1.7 R=Initialize Robot&quot;">​</a></h4><p>Activate robot arm (Servo on) and switch to real robot mode.<br> (Rising Edge)</p><h4 id="_1-8-h-temporary-collision-off" tabindex="-1">1.8 H=Temporary Collision off <a class="header-anchor" href="#_1-8-h-temporary-collision-off" aria-label="Permalink to &quot;1.8 H=Temporary Collision off&quot;">​</a></h4><p>Turns off external crash detection.<br> (High State)</p><h4 id="_1-9-h-auto-initialize-key" tabindex="-1">1.9 H=Auto-Initialize Key <a class="header-anchor" href="#_1-9-h-auto-initialize-key" aria-label="Permalink to &quot;1.9 H=Auto-Initialize Key&quot;">​</a></h4><p>Key port for using the &#39;Automatic Activation with Key&#39; setting.<br> (High State)</p><h4 id="_1-10-r-resume-from-out-coll-stop" tabindex="-1">1.10 R=Resume from Out Coll. Stop <a class="header-anchor" href="#_1-10-r-resume-from-out-coll-stop" aria-label="Permalink to &quot;1.10 R=Resume from Out Coll. Stop&quot;">​</a></h4><p>Release the stop due to external collision detection.<br> (Rising Edge)</p><h4 id="_1-11-r-point-add" tabindex="-1">1.11 R=Point Add <a class="header-anchor" href="#_1-11-r-point-add" aria-label="Permalink to &quot;1.11 R=Point Add&quot;">​</a></h4><p>Add the current position-information of the robot arm as a point under the Move function.<br> (Rising Edge)</p><h4 id="_1-12-r-start-program-repeat" tabindex="-1">1.12 R=Start Program (Repeat) <a class="header-anchor" href="#_1-12-r-start-program-repeat" aria-label="Permalink to &quot;1.12 R=Start Program (Repeat)&quot;">​</a></h4><p>Idle: Repeat starting the program currently loaded.<br> Pause: Restart the program.<br> (Rising Edge)</p><h4 id="_1-13-r-approach-to-begin" tabindex="-1">1.13 R=Approach to Begin <a class="header-anchor" href="#_1-13-r-approach-to-begin" aria-label="Permalink to &quot;1.13 R=Approach to Begin&quot;">​</a></h4><p>Move to the starting position (Home-pos) defined in the program currently loaded.<br> (Rising Edge)</p><h4 id="_1-14-r-program-resume" tabindex="-1">1.14 R=Program Resume <a class="header-anchor" href="#_1-14-r-program-resume" aria-label="Permalink to &quot;1.14 R=Program Resume&quot;">​</a></h4><p>Restart the paused program.<br> (Rising Edge)</p><h4 id="_1-15-h-quick-freedrive-change" tabindex="-1">1.15 H=Quick Freedrive Change <a class="header-anchor" href="#_1-15-h-quick-freedrive-change" aria-label="Permalink to &quot;1.15 H=Quick Freedrive Change&quot;">​</a></h4><p>It&#39;s a function to grab the Servo-lock when exit the direct teaching mode.<br> (High State)</p><h4 id="_1-16-r-pause-f-resume-program" tabindex="-1">1.16 R=Pause / F=Resume Program <a class="header-anchor" href="#_1-16-r-pause-f-resume-program" aria-label="Permalink to &quot;1.16 R=Pause / F=Resume Program&quot;">​</a></h4><p>R=Pause the program.<br> F=Restart the program.</p><h4 id="_1-17-f-pause-r-resume-program" tabindex="-1">1.17 F=Pause / R=Resume Program <a class="header-anchor" href="#_1-17-f-pause-r-resume-program" aria-label="Permalink to &quot;1.17 F=Pause / R=Resume Program&quot;">​</a></h4><p>F=Pause the program.<br> R=Restart the program.</p><h4 id="_1-18-h-speed-100-f-0" tabindex="-1">1.18 H=Speed 100% / F=0% <a class="header-anchor" href="#_1-18-h-speed-100-f-0" aria-label="Permalink to &quot;1.18 H=Speed 100% / F=0%&quot;">​</a></h4><p>H=Set the speed bar to 100%.<br> F=Set the speed bar to 0%.</p><h4 id="_1-19-r-load-default-program" tabindex="-1">1.19 R=Load Default Program <a class="header-anchor" href="#_1-19-r-load-default-program" aria-label="Permalink to &quot;1.19 R=Load Default Program&quot;">​</a></h4><p>Loads a program set as the default program.<br> (Rising Edge)</p><h4 id="_1-20-f-robot-arm-power-down" tabindex="-1">1.20 F=Robot Arm Power Down <a class="header-anchor" href="#_1-20-f-robot-arm-power-down" aria-label="Permalink to &quot;1.20 F=Robot Arm Power Down&quot;">​</a></h4><p>Turn off the DC power applied to the robot&#39;s arm.<br> (Falling Edge)</p><h4 id="_1-21-r-touch-sensing" tabindex="-1">1.21 R=Touch Sensing <a class="header-anchor" href="#_1-21-r-touch-sensing" aria-label="Permalink to &quot;1.21 R=Touch Sensing&quot;">​</a></h4><p>When using the touch sensing function, this is the port that connects the touch sensing signal output-line from the welding machine.<br> (Rising Edge)</p><h4 id="_1-22-f-touch-sensing" tabindex="-1">1.22 F=Touch Sensing <a class="header-anchor" href="#_1-22-f-touch-sensing" aria-label="Permalink to &quot;1.22 F=Touch Sensing&quot;">​</a></h4><p>When using the touch sensing function, this is the port that connects the touch sensing signal output-line from the welding machine.<br> (Falling Edge)</p><h4 id="_1-23-h-no-arc" tabindex="-1">1.23 H=No Arc <a class="header-anchor" href="#_1-23-h-no-arc" aria-label="Permalink to &quot;1.23 H=No Arc&quot;">​</a></h4><p>When a signal is on (if high-state), activate the No-Arc function.<br> (High State)</p><h4 id="_1-24-h-program-start-block" tabindex="-1">1.24 H=Program Start Block <a class="header-anchor" href="#_1-24-h-program-start-block" aria-label="Permalink to &quot;1.24 H=Program Start Block&quot;">​</a></h4><p>The signal cannot start the program while it is in the high-state.<br> (High State)</p><h4 id="_1-25-r-ext-joint-0-plus-f-stop" tabindex="-1">1.25 R=Ext.Joint 0 Plus / F=stop <a class="header-anchor" href="#_1-25-r-ext-joint-0-plus-f-stop" aria-label="Permalink to &quot;1.25 R=Ext.Joint 0 Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 0 moves in the (+) direction / F=stop</p><h4 id="_1-26-r-ext-joint-0-minus-f-stop" tabindex="-1">1.26 R=Ext.Joint 0 Minus / F=stop <a class="header-anchor" href="#_1-26-r-ext-joint-0-minus-f-stop" aria-label="Permalink to &quot;1.26 R=Ext.Joint 0 Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 0 moves in the (-) direction / F=stop</p><h4 id="_1-27-r-ext-joint-1-plus-f-stop" tabindex="-1">1.27 R=Ext.Joint 1 Plus / F=stop <a class="header-anchor" href="#_1-27-r-ext-joint-1-plus-f-stop" aria-label="Permalink to &quot;1.27 R=Ext.Joint 1 Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 1 moves in the (+) direction / F=stop</p><h4 id="_1-28-r-ext-joint-1-minus-f-stop" tabindex="-1">1.28 R=Ext.Joint 1 Minus / F=stop <a class="header-anchor" href="#_1-28-r-ext-joint-1-minus-f-stop" aria-label="Permalink to &quot;1.28 R=Ext.Joint 1 Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 1 moves in the (-) direction / F=stop</p><h4 id="_1-29-r-ext-joint-2-plus-f-stop" tabindex="-1">1.29 R=Ext.Joint 2 Plus / F=stop <a class="header-anchor" href="#_1-29-r-ext-joint-2-plus-f-stop" aria-label="Permalink to &quot;1.29 R=Ext.Joint 2 Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 2 moves in the (+) direction / F=stop</p><h4 id="_1-30-r-ext-joint-2-minus-f-stop" tabindex="-1">1.30 R=Ext.Joint 2 Minus / F=stop <a class="header-anchor" href="#_1-30-r-ext-joint-2-minus-f-stop" aria-label="Permalink to &quot;1.30 R=Ext.Joint 2 Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 2 moves in the (-) direction / F=stop</p><h4 id="_1-31-h-safety-speed" tabindex="-1">1.31 H=Safety Speed <a class="header-anchor" href="#_1-31-h-safety-speed" aria-label="Permalink to &quot;1.31 H=Safety Speed&quot;">​</a></h4><p>Switch the robot arm&#39;s motion speed to the safe speed range.<br> (High State)</p><h4 id="_1-32-f-user-coord-0-←-tcp-frame" tabindex="-1">1.32 F=User Coord 0 ← TCP frame <a class="header-anchor" href="#_1-32-f-user-coord-0-←-tcp-frame" aria-label="Permalink to &quot;1.32 F=User Coord 0 ← TCP frame&quot;">​</a></h4><p>Change the setting value of user coordinate 0 to the position/rotation of the TCP coordinate system of the current robot arm.<br> (Falling Edge)</p><h4 id="_1-33-f-user-coord-1-←-tcp-frame" tabindex="-1">1.33 F=User Coord 1 ← TCP frame <a class="header-anchor" href="#_1-33-f-user-coord-1-←-tcp-frame" aria-label="Permalink to &quot;1.33 F=User Coord 1 ← TCP frame&quot;">​</a></h4><p>Change the setting value of user coordinate 1 to the position/rotation of the TCP coordinate system of the current robot arm.<br> (Falling Edge)</p><h4 id="_1-34-f-user-coord-2-←-tcp-frame" tabindex="-1">1.34 F=User Coord 2 ← TCP frame <a class="header-anchor" href="#_1-34-f-user-coord-2-←-tcp-frame" aria-label="Permalink to &quot;1.34 F=User Coord 2 ← TCP frame&quot;">​</a></h4><p>Change the setting value of user coordinate 2 to the position/rotation of the TCP coordinate system of the current robot arm.<br> (Falling Edge)</p><h4 id="_1-35-f-load-run-program-table" tabindex="-1">1.35 F=Load &amp; Run Program Table <a class="header-anchor" href="#_1-35-f-load-run-program-table" aria-label="Permalink to &quot;1.35 F=Load &amp; Run Program Table&quot;">​</a></h4><p>Loads and plays the program set at the number of the corresponding input port in the Program Table.<br> (Falling Edge)</p><h4 id="_1-36-r-start-prog-once-f-stop-prog" tabindex="-1">1.36 R=Start Prog. (Once) / F=Stop Prog. <a class="header-anchor" href="#_1-36-r-start-prog-once-f-stop-prog" aria-label="Permalink to &quot;1.36 R=Start Prog. (Once) / F=Stop Prog.&quot;">​</a></h4><p>R=Run the loaded program once / F=Stop the program</p><h4 id="_1-37-r-start-prog-repeat-f-stop-prog" tabindex="-1">1.37 R=Start Prog. (Repeat) / F=Stop Prog. <a class="header-anchor" href="#_1-37-r-start-prog-repeat-f-stop-prog" aria-label="Permalink to &quot;1.37 R=Start Prog. (Repeat) / F=Stop Prog.&quot;">​</a></h4><p>R=Run the loaded program repeatedly / F=Stop the program</p><h4 id="_1-38-f-change-global-pinpoint-s-pos" tabindex="-1">1.38 F=Change Global Pinpoint #’s Pos <a class="header-anchor" href="#_1-38-f-change-global-pinpoint-s-pos" aria-label="Permalink to &quot;1.38 F=Change Global Pinpoint #’s Pos&quot;">​</a></h4><p>Save the global pin-point as the current point value of the robot arm.<br> (Falling Edge)</p><h4 id="_1-39-r-ext-joint-0-slow-plus-f-stop" tabindex="-1">1.39 R=EXT.Joint 0 Slow Plus / F=stop <a class="header-anchor" href="#_1-39-r-ext-joint-0-slow-plus-f-stop" aria-label="Permalink to &quot;1.39 R=EXT.Joint 0 Slow Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 0 slowly moves in the (+) direction / F=stop</p><h4 id="_1-40-r-ext-joint-0-slow-minus-f-stop" tabindex="-1">1.40 R=EXT.Joint 0 Slow Minus / F=stop <a class="header-anchor" href="#_1-40-r-ext-joint-0-slow-minus-f-stop" aria-label="Permalink to &quot;1.40 R=EXT.Joint 0 Slow Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 0 slowly moves in the (-) direction / F=stop</p><h4 id="_1-41-r-ext-joint-1-slow-plus-f-stop" tabindex="-1">1.41 R=EXT.Joint 1 Slow Plus / F=stop <a class="header-anchor" href="#_1-41-r-ext-joint-1-slow-plus-f-stop" aria-label="Permalink to &quot;1.41 R=EXT.Joint 1 Slow Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 1 slowly moves in the (+) direction / F=stop</p><h4 id="_1-42-r-ext-joint-1-slow-minus-f-stop" tabindex="-1">1.42 R=EXT.Joint 1 Slow Minus / F=stop <a class="header-anchor" href="#_1-42-r-ext-joint-1-slow-minus-f-stop" aria-label="Permalink to &quot;1.42 R=EXT.Joint 1 Slow Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 1 slowly moves in the (-) direction / F=stop</p><h4 id="_1-43-r-ext-joint-2-slow-plus-f-stop" tabindex="-1">1.43 R=EXT.Joint 2 Slow Plus / F=stop <a class="header-anchor" href="#_1-43-r-ext-joint-2-slow-plus-f-stop" aria-label="Permalink to &quot;1.43 R=EXT.Joint 2 Slow Plus / F=stop&quot;">​</a></h4><p>R=Additional axis 2 slowly moves in the (+) direction / F=stop</p><h4 id="_1-44-r-ext-joint-2-slow-minus-f-stop" tabindex="-1">1.44 R=EXT.Joint 2 Slow Minus / F=stop <a class="header-anchor" href="#_1-44-r-ext-joint-2-slow-minus-f-stop" aria-label="Permalink to &quot;1.44 R=EXT.Joint 2 Slow Minus / F=stop&quot;">​</a></h4><p>R=Additional axis 2 slowly moves in the (-) direction / F=stop</p><h4 id="_1-45-r-reset-sos" tabindex="-1">1.45 R=Reset SOS <a class="header-anchor" href="#_1-45-r-reset-sos" aria-label="Permalink to &quot;1.45 R=Reset SOS&quot;">​</a></h4><p>Initialize (reset) the SOS state.<br> (Rising Edge)</p><h4 id="_1-46-f-reset-sos" tabindex="-1">1.46 F=Reset SOS <a class="header-anchor" href="#_1-46-f-reset-sos" aria-label="Permalink to &quot;1.46 F=Reset SOS&quot;">​</a></h4><p>Initialize (reset) the SOS state.<br> (Falling Edge)</p><h4 id="_1-47-r-delete-point" tabindex="-1">1.47 R=Delete Point <a class="header-anchor" href="#_1-47-r-delete-point" aria-label="Permalink to &quot;1.47 R=Delete Point&quot;">​</a></h4><p>Deletes the taught point.<br> (Rising Edge)</p><h4 id="_1-48-r-add-arc-on" tabindex="-1">1.48 R=Add ARC-On <a class="header-anchor" href="#_1-48-r-add-arc-on" aria-label="Permalink to &quot;1.48 R=Add ARC-On&quot;">​</a></h4><p>Adds the Arc-On function.</p><h4 id="_1-49-r-add-arc-off" tabindex="-1">1.49 R=Add ARC-Off <a class="header-anchor" href="#_1-49-r-add-arc-off" aria-label="Permalink to &quot;1.49 R=Add ARC-Off&quot;">​</a></h4><p>Adds the Arc-Off function.</p><h4 id="_1-50-h-speed-75-l-0" tabindex="-1">1.50 H=Speed 75% / L=0% <a class="header-anchor" href="#_1-50-h-speed-75-l-0" aria-label="Permalink to &quot;1.50 H=Speed 75% / L=0%&quot;">​</a></h4><p>H = Speed 75% / L = Speed 0%</p><h4 id="_1-51-h-speed-50-l-0" tabindex="-1">1.51 H=Speed 50% / L=0% <a class="header-anchor" href="#_1-51-h-speed-50-l-0" aria-label="Permalink to &quot;1.51 H=Speed 50% / L=0%&quot;">​</a></h4><p>H = Speed 50% / L = Speed 0%</p><h4 id="_1-52-h-speed-25-l-0" tabindex="-1">1.52 H=Speed 25% / L=0% <a class="header-anchor" href="#_1-52-h-speed-25-l-0" aria-label="Permalink to &quot;1.52 H=Speed 25% / L=0%&quot;">​</a></h4><p>H = Speed 25% / L = Speed 0%</p><h4 id="_1-53-h-speed-10-l-0" tabindex="-1">1.53 H=Speed 10% / L=0% <a class="header-anchor" href="#_1-53-h-speed-10-l-0" aria-label="Permalink to &quot;1.53 H=Speed 10% / L=0%&quot;">​</a></h4><p>H = Speed 10% / L = Speed 0%</p><h4 id="_1-54-f-pause-program" tabindex="-1">1.54 F=Pause Program <a class="header-anchor" href="#_1-54-f-pause-program" aria-label="Permalink to &quot;1.54 F=Pause Program&quot;">​</a></h4><p>Pauses the program.<br> (Falling Edge)</p><h4 id="_1-55-h-block-freedrive-button" tabindex="-1">1.55 H=Block Freedrive Button <a class="header-anchor" href="#_1-55-h-block-freedrive-button" aria-label="Permalink to &quot;1.55 H=Block Freedrive Button&quot;">​</a></h4><p>Blocks direct teaching when High.</p><h4 id="_1-56-l-block-freedrive-button" tabindex="-1">1.56 L=Block Freedrive Button <a class="header-anchor" href="#_1-56-l-block-freedrive-button" aria-label="Permalink to &quot;1.56 L=Block Freedrive Button&quot;">​</a></h4><p>Blocks direct teaching when Low.</p><h4 id="_1-57-duplex-for-safety" tabindex="-1">1.57 Duplex for Safety <a class="header-anchor" href="#_1-57-duplex-for-safety" aria-label="Permalink to &quot;1.57 Duplex for Safety&quot;">​</a></h4><p>Implements a redundant input function. The input is recognized only when both input signals are High.</p><h4 id="_1-58-f-stop-program" tabindex="-1">1.58 F=Stop Program <a class="header-anchor" href="#_1-58-f-stop-program" aria-label="Permalink to &quot;1.58 F=Stop Program&quot;">​</a></h4><p>Stops the program.<br> (Falling Edge)</p><h4 id="_1-59-f-reset-sos-ems-state" tabindex="-1">1.59 F=Reset SOS / EMS State <a class="header-anchor" href="#_1-59-f-reset-sos-ems-state" aria-label="Permalink to &quot;1.59 F=Reset SOS / EMS State&quot;">​</a></h4><p>Resets the SOS alarm. <br> The robot arm power is cut off, the same as when the emergency stop switch is activated.</p><h4 id="_1-60-f-reset-modbus-server" tabindex="-1">1.60 F=Reset Modbus Server <a class="header-anchor" href="#_1-60-f-reset-modbus-server" aria-label="Permalink to &quot;1.60 F=Reset Modbus Server&quot;">​</a></h4><p>Resets the Modbus server.</p><h4 id="_1-61-r-run-user-script-0" tabindex="-1">1.61 R=Run User Script 0 <a class="header-anchor" href="#_1-61-r-run-user-script-0" aria-label="Permalink to &quot;1.61 R=Run User Script 0&quot;">​</a></h4><p>Executes User Script 0.</p><h4 id="_1-62-r-run-user-script-1" tabindex="-1">1.62 R=Run User Script 1 <a class="header-anchor" href="#_1-62-r-run-user-script-1" aria-label="Permalink to &quot;1.62 R=Run User Script 1&quot;">​</a></h4><p>Executes User Script 1.</p><h4 id="_1-63-r-run-user-script-2" tabindex="-1">1.63 R=Run User Script 2 <a class="header-anchor" href="#_1-63-r-run-user-script-2" aria-label="Permalink to &quot;1.63 R=Run User Script 2&quot;">​</a></h4><p>Executes User Script 2.</p><h4 id="_1-64-r-run-user-script-3" tabindex="-1">1.64 R=Run User Script 3 <a class="header-anchor" href="#_1-64-r-run-user-script-3" aria-label="Permalink to &quot;1.64 R=Run User Script 3&quot;">​</a></h4><p>Executes User Script 3.</p><h4 id="_1-65-r-run-user-script-4" tabindex="-1">1.65 R=Run User Script 4 <a class="header-anchor" href="#_1-65-r-run-user-script-4" aria-label="Permalink to &quot;1.65 R=Run User Script 4&quot;">​</a></h4><p>Executes User Script 4.</p><h4 id="_1-66-r-run-user-script-5" tabindex="-1">1.66 R=Run User Script 5 <a class="header-anchor" href="#_1-66-r-run-user-script-5" aria-label="Permalink to &quot;1.66 R=Run User Script 5&quot;">​</a></h4><p>Executes User Script 5.</p><h4 id="_1-67-r-run-user-script-6" tabindex="-1">1.67 R=Run User Script 6 <a class="header-anchor" href="#_1-67-r-run-user-script-6" aria-label="Permalink to &quot;1.67 R=Run User Script 6&quot;">​</a></h4><p>Executes User Script 6.</p><h4 id="_1-68-r-run-user-script-7" tabindex="-1">1.68 R=Run User Script 7 <a class="header-anchor" href="#_1-68-r-run-user-script-7" aria-label="Permalink to &quot;1.68 R=Run User Script 7&quot;">​</a></h4><p>Executes User Script 7.</p><h4 id="_1-69-r-run-user-script-8" tabindex="-1">1.69 R=Run User Script 8 <a class="header-anchor" href="#_1-69-r-run-user-script-8" aria-label="Permalink to &quot;1.69 R=Run User Script 8&quot;">​</a></h4><p>Executes User Script 8.</p><h4 id="_1-70-r-run-user-script-9" tabindex="-1">1.70 R=Run User Script 9 <a class="header-anchor" href="#_1-70-r-run-user-script-9" aria-label="Permalink to &quot;1.70 R=Run User Script 9&quot;">​</a></h4><p>Executes User Script 9.</p><h4 id="_1-71-h-ignore-self-collision" tabindex="-1">1.71 H=Ignore Self Collision <a class="header-anchor" href="#_1-71-h-ignore-self-collision" aria-label="Permalink to &quot;1.71 H=Ignore Self Collision&quot;">​</a></h4><p>Ignores self-collision when High.</p><h4 id="_1-72-h-conditional-script-exe-key" tabindex="-1">1.72 H=Conditional Script Exe Key <a class="header-anchor" href="#_1-72-h-conditional-script-exe-key" aria-label="Permalink to &quot;1.72 H=Conditional Script Exe Key&quot;">​</a></h4><p>Executes the function assigned to the User Script when High.</p><h4 id="_1-73-r-speed-50-f-100" tabindex="-1">1.73 R=Speed 50% / F=100% <a class="header-anchor" href="#_1-73-r-speed-50-f-100" aria-label="Permalink to &quot;1.73 R=Speed 50% / F=100%&quot;">​</a></h4><p>R = Speed 50% / F = Speed 100%</p><h4 id="_1-74-r-speed-25-f-100" tabindex="-1">1.74 R=Speed 25% / F=100% <a class="header-anchor" href="#_1-74-r-speed-25-f-100" aria-label="Permalink to &quot;1.74 R=Speed 25% / F=100%&quot;">​</a></h4><p>R = Speed 25% / F = Speed 100%</p><h4 id="_1-75-h-speed-100-l-75" tabindex="-1">1.75 H=Speed 100% / L=75% <a class="header-anchor" href="#_1-75-h-speed-100-l-75" aria-label="Permalink to &quot;1.75 H=Speed 100% / L=75%&quot;">​</a></h4><p>H = Speed 100% / L = Speed 75%</p><h4 id="_1-76-h-speed-100-l-50" tabindex="-1">1.76 H=Speed 100% / L=50% <a class="header-anchor" href="#_1-76-h-speed-100-l-50" aria-label="Permalink to &quot;1.76 H=Speed 100% / L=50%&quot;">​</a></h4><p>H = Speed 100% / L = Speed 50%</p><h4 id="_1-77-h-speed-100-l-25" tabindex="-1">1.77 H=Speed 100% / L=25% <a class="header-anchor" href="#_1-77-h-speed-100-l-25" aria-label="Permalink to &quot;1.77 H=Speed 100% / L=25%&quot;">​</a></h4><p>H = Speed 100% / L = Speed 25%</p><h4 id="_1-78-r-reset-ui-connection" tabindex="-1">1.78 R=Reset UI Connection <a class="header-anchor" href="#_1-78-r-reset-ui-connection" aria-label="Permalink to &quot;1.78 R=Reset UI Connection&quot;">​</a></h4><p>Disconnects the RB UI connection between the control box and the currently connected tablet.</p><h4 id="_1-79-h-block-sss-function" tabindex="-1">1.79 H=Block SSS Function <a class="header-anchor" href="#_1-79-h-block-sss-function" aria-label="Permalink to &quot;1.79 H=Block SSS Function&quot;">​</a></h4><p>Prevents the alarm generated when the SSS key is released by setting the SSS key to the shorted state.</p><h4 id="_1-80-h-auto-sss-resume-key" tabindex="-1">1.80 H=Auto SSS Resume Key <a class="header-anchor" href="#_1-80-h-auto-sss-resume-key" aria-label="Permalink to &quot;1.80 H=Auto SSS Resume Key&quot;">​</a></h4><p>Restarts the function that was paused when the SSS key was released.<br> (In this case, the SSS must be shorted again.)</p><h4 id="_1-81-r-robot-arm-powerdown" tabindex="-1">1.81 R=Robot Arm PowerDown <a class="header-anchor" href="#_1-81-r-robot-arm-powerdown" aria-label="Permalink to &quot;1.81 R=Robot Arm PowerDown&quot;">​</a></h4><p>Turns off the robot power.</p><h4 id="_1-82-h-block-d-in-special-functions" tabindex="-1">1.82 H=Block D.In Special Functions <a class="header-anchor" href="#_1-82-h-block-d-in-special-functions" aria-label="Permalink to &quot;1.82 H=Block D.In Special Functions&quot;">​</a></h4><p>Disables Digital Input special functions on Digital ports with lower numbers than the assigned port when High.<br> (If this function is assigned to DI 8, the functions assigned to DI 0 to 7 are disabled.)</p><h4 id="_1-83-l-block-d-in-special-functions" tabindex="-1">1.83 L=Block D.In Special Functions <a class="header-anchor" href="#_1-83-l-block-d-in-special-functions" aria-label="Permalink to &quot;1.83 L=Block D.In Special Functions&quot;">​</a></h4><p>Disables Digital Input special functions on Digital ports with lower numbers than the assigned port when Low.<br> (If this function is assigned to DI 8, the functions assigned to DI 0 to 7 are disabled.)</p><h4 id="_1-84-r-global-speed-bar" tabindex="-1">1.84 R=Global Speed Bar + <a class="header-anchor" href="#_1-84-r-global-speed-bar" aria-label="Permalink to &quot;1.84 R=Global Speed Bar +&quot;">​</a></h4><p>Increases the speed control bar by 10%.</p><h4 id="_1-85-r-global-speed-bar" tabindex="-1">1.85 R=Global Speed Bar - <a class="header-anchor" href="#_1-85-r-global-speed-bar" aria-label="Permalink to &quot;1.85 R=Global Speed Bar -&quot;">​</a></h4><p>Decreases the speed control bar by 10%.</p><h4 id="_1-86-r-robot-jog-joint-0" tabindex="-1">1.86 R=Robot Jog Joint 0 + <a class="header-anchor" href="#_1-86-r-robot-jog-joint-0" aria-label="Permalink to &quot;1.86 R=Robot Jog Joint 0 +&quot;">​</a></h4><p>Moves Joint 0 in the positive direction.</p><h4 id="_1-87-r-robot-jog-joint-0" tabindex="-1">1.87 R=Robot Jog Joint 0 - <a class="header-anchor" href="#_1-87-r-robot-jog-joint-0" aria-label="Permalink to &quot;1.87 R=Robot Jog Joint 0 -&quot;">​</a></h4><p>Moves Joint 0 in the negative direction.</p><h4 id="_1-88-r-robot-jog-joint-1" tabindex="-1">1.88 R=Robot Jog Joint 1 + <a class="header-anchor" href="#_1-88-r-robot-jog-joint-1" aria-label="Permalink to &quot;1.88 R=Robot Jog Joint 1 +&quot;">​</a></h4><p>Moves Joint 1 in the positive direction.</p><h4 id="_1-89-r-robot-jog-joint-1" tabindex="-1">1.89 R=Robot Jog Joint 1 - <a class="header-anchor" href="#_1-89-r-robot-jog-joint-1" aria-label="Permalink to &quot;1.89 R=Robot Jog Joint 1 -&quot;">​</a></h4><p>Moves Joint 1 in the negative direction.</p><h4 id="_1-90-r-robot-jog-joint-2" tabindex="-1">1.90 R=Robot Jog Joint 2 + <a class="header-anchor" href="#_1-90-r-robot-jog-joint-2" aria-label="Permalink to &quot;1.90 R=Robot Jog Joint 2 +&quot;">​</a></h4><p>Moves Joint 2 in the positive direction.</p><h4 id="_1-91-r-robot-jog-joint-2" tabindex="-1">1.91 R=Robot Jog Joint 2 - <a class="header-anchor" href="#_1-91-r-robot-jog-joint-2" aria-label="Permalink to &quot;1.91 R=Robot Jog Joint 2 -&quot;">​</a></h4><p>Moves Joint 2 in the negative direction.</p><h4 id="_1-92-r-robot-jog-joint-3" tabindex="-1">1.92 R=Robot Jog Joint 3 + <a class="header-anchor" href="#_1-92-r-robot-jog-joint-3" aria-label="Permalink to &quot;1.92 R=Robot Jog Joint 3 +&quot;">​</a></h4><p>Moves Joint 3 in the positive direction.</p><h4 id="_1-93-r-robot-jog-joint-3" tabindex="-1">1.93 R=Robot Jog Joint 3 - <a class="header-anchor" href="#_1-93-r-robot-jog-joint-3" aria-label="Permalink to &quot;1.93 R=Robot Jog Joint 3 -&quot;">​</a></h4><p>Moves Joint 3 in the negative direction.</p><h4 id="_1-94-r-robot-jog-joint-4" tabindex="-1">1.94 R=Robot Jog Joint 4 + <a class="header-anchor" href="#_1-94-r-robot-jog-joint-4" aria-label="Permalink to &quot;1.94 R=Robot Jog Joint 4 +&quot;">​</a></h4><p>Moves Joint 4 in the positive direction.</p><h4 id="_1-95-r-robot-jog-joint-4" tabindex="-1">1.95 R=Robot Jog Joint 4 - <a class="header-anchor" href="#_1-95-r-robot-jog-joint-4" aria-label="Permalink to &quot;1.95 R=Robot Jog Joint 4 -&quot;">​</a></h4><p>Moves Joint 4 in the negative direction.</p><h4 id="_1-96-r-robot-jog-joint-5" tabindex="-1">1.96 R=Robot Jog Joint 5 + <a class="header-anchor" href="#_1-96-r-robot-jog-joint-5" aria-label="Permalink to &quot;1.96 R=Robot Jog Joint 5 +&quot;">​</a></h4><p>Moves Joint 5 in the positive direction.</p><h4 id="_1-97-r-robot-jog-joint-5" tabindex="-1">1.97 R=Robot Jog Joint 5 - <a class="header-anchor" href="#_1-97-r-robot-jog-joint-5" aria-label="Permalink to &quot;1.97 R=Robot Jog Joint 5 -&quot;">​</a></h4><p>Moves Joint 5 in the negative direction.</p><h4 id="_1-98-r-robot-jog-global-x" tabindex="-1">1.98 R=Robot Jog Global X + <a class="header-anchor" href="#_1-98-r-robot-jog-global-x" aria-label="Permalink to &quot;1.98 R=Robot Jog Global X +&quot;">​</a></h4><p>Moves in the positive X direction in the Global coordinate system.</p><h4 id="_1-99-r-robot-jog-global-x" tabindex="-1">1.99 R=Robot Jog Global X - <a class="header-anchor" href="#_1-99-r-robot-jog-global-x" aria-label="Permalink to &quot;1.99 R=Robot Jog Global X -&quot;">​</a></h4><p>Moves in the negative X direction in the Global coordinate system.</p><h4 id="_1-100-r-robot-jog-global-y" tabindex="-1">1.100 R=Robot Jog Global Y + <a class="header-anchor" href="#_1-100-r-robot-jog-global-y" aria-label="Permalink to &quot;1.100 R=Robot Jog Global Y +&quot;">​</a></h4><p>Moves in the positive Y direction in the Global coordinate system.</p><h4 id="_1-101-r-robot-jog-global-y" tabindex="-1">1.101 R=Robot Jog Global Y - <a class="header-anchor" href="#_1-101-r-robot-jog-global-y" aria-label="Permalink to &quot;1.101 R=Robot Jog Global Y -&quot;">​</a></h4><p>Moves in the negative Y direction in the Global coordinate system.</p><h4 id="_1-102-r-robot-jog-global-z" tabindex="-1">1.102 R=Robot Jog Global Z + <a class="header-anchor" href="#_1-102-r-robot-jog-global-z" aria-label="Permalink to &quot;1.102 R=Robot Jog Global Z +&quot;">​</a></h4><p>Moves in the positive Z direction in the Global coordinate system.</p><h4 id="_1-103-r-robot-jog-global-z" tabindex="-1">1.103 R=Robot Jog Global Z - <a class="header-anchor" href="#_1-103-r-robot-jog-global-z" aria-label="Permalink to &quot;1.103 R=Robot Jog Global Z -&quot;">​</a></h4><p>Moves in the negative Z direction in the Global coordinate system.</p><h4 id="_1-104-r-robot-jog-global-rx" tabindex="-1">1.104 R=Robot Jog Global RX + <a class="header-anchor" href="#_1-104-r-robot-jog-global-rx" aria-label="Permalink to &quot;1.104 R=Robot Jog Global RX +&quot;">​</a></h4><p>Moves in the positive RX direction in the Global coordinate system.</p><h4 id="_1-105-r-robot-jog-global-rx" tabindex="-1">1.105 R=Robot Jog Global RX - <a class="header-anchor" href="#_1-105-r-robot-jog-global-rx" aria-label="Permalink to &quot;1.105 R=Robot Jog Global RX -&quot;">​</a></h4><p>Moves in the negative RX direction in the Global coordinate system.</p><h4 id="_1-106-r-robot-jog-global-ry" tabindex="-1">1.106 R=Robot Jog Global RY + <a class="header-anchor" href="#_1-106-r-robot-jog-global-ry" aria-label="Permalink to &quot;1.106 R=Robot Jog Global RY +&quot;">​</a></h4><p>Moves in the positive RY direction in the Global coordinate system.</p><h4 id="_1-107-r-robot-jog-global-ry" tabindex="-1">1.107 R=Robot Jog Global RY - <a class="header-anchor" href="#_1-107-r-robot-jog-global-ry" aria-label="Permalink to &quot;1.107 R=Robot Jog Global RY -&quot;">​</a></h4><p>Moves in the negative RY direction in the Global coordinate system.</p><h4 id="_1-108-r-robot-jog-global-rz" tabindex="-1">1.108 R=Robot Jog Global RZ + <a class="header-anchor" href="#_1-108-r-robot-jog-global-rz" aria-label="Permalink to &quot;1.108 R=Robot Jog Global RZ +&quot;">​</a></h4><p>Moves in the positive RZ direction in the Global coordinate system.</p><h4 id="_1-109-r-robot-jog-global-rz" tabindex="-1">1.109 R=Robot Jog Global RZ - <a class="header-anchor" href="#_1-109-r-robot-jog-global-rz" aria-label="Permalink to &quot;1.109 R=Robot Jog Global RZ -&quot;">​</a></h4><p>Moves in the negative RZ direction in the Global coordinate system.</p><h4 id="_1-110-r-robot-jog-local-x" tabindex="-1">1.110 R=Robot Jog Local X + <a class="header-anchor" href="#_1-110-r-robot-jog-local-x" aria-label="Permalink to &quot;1.110 R=Robot Jog Local X +&quot;">​</a></h4><p>Moves in the positive X direction in the Local coordinate system.</p><h4 id="_1-111-r-robot-jog-local-x" tabindex="-1">1.111 R=Robot Jog Local X - <a class="header-anchor" href="#_1-111-r-robot-jog-local-x" aria-label="Permalink to &quot;1.111 R=Robot Jog Local X -&quot;">​</a></h4><p>Moves in the negative X direction in the Local coordinate system.</p><h4 id="_1-112-r-robot-jog-local-y" tabindex="-1">1.112 R=Robot Jog Local Y + <a class="header-anchor" href="#_1-112-r-robot-jog-local-y" aria-label="Permalink to &quot;1.112 R=Robot Jog Local Y +&quot;">​</a></h4><p>Moves in the positive Y direction in the Local coordinate system.</p><h4 id="_1-113-r-robot-jog-local-y" tabindex="-1">1.113 R=Robot Jog Local Y - <a class="header-anchor" href="#_1-113-r-robot-jog-local-y" aria-label="Permalink to &quot;1.113 R=Robot Jog Local Y -&quot;">​</a></h4><p>Moves in the negative Y direction in the Local coordinate system.</p><h4 id="_1-114-r-robot-jog-local-z" tabindex="-1">1.114 R=Robot Jog Local Z + <a class="header-anchor" href="#_1-114-r-robot-jog-local-z" aria-label="Permalink to &quot;1.114 R=Robot Jog Local Z +&quot;">​</a></h4><p>Moves in the positive Z direction in the Local coordinate system.</p><h4 id="_1-115-r-robot-jog-local-z" tabindex="-1">1.115 R=Robot Jog Local Z - <a class="header-anchor" href="#_1-115-r-robot-jog-local-z" aria-label="Permalink to &quot;1.115 R=Robot Jog Local Z -&quot;">​</a></h4><p>Moves in the negative Z direction in the Local coordinate system.</p><h4 id="_1-116-r-robot-jog-local-rx" tabindex="-1">1.116 R=Robot Jog Local RX + <a class="header-anchor" href="#_1-116-r-robot-jog-local-rx" aria-label="Permalink to &quot;1.116 R=Robot Jog Local RX +&quot;">​</a></h4><p>Moves in the positive RX direction in the Local coordinate system.</p><h4 id="_1-117-r-robot-jog-local-rx" tabindex="-1">1.117 R=Robot Jog Local RX - <a class="header-anchor" href="#_1-117-r-robot-jog-local-rx" aria-label="Permalink to &quot;1.117 R=Robot Jog Local RX -&quot;">​</a></h4><p>Moves in the negative RX direction in the Local coordinate system.</p><h4 id="_1-118-r-robot-jog-local-ry" tabindex="-1">1.118 R=Robot Jog Local RY + <a class="header-anchor" href="#_1-118-r-robot-jog-local-ry" aria-label="Permalink to &quot;1.118 R=Robot Jog Local RY +&quot;">​</a></h4><p>Moves in the positive RY direction in the Local coordinate system.</p><h4 id="_1-119-r-robot-jog-local-ry" tabindex="-1">1.119 R=Robot Jog Local RY - <a class="header-anchor" href="#_1-119-r-robot-jog-local-ry" aria-label="Permalink to &quot;1.119 R=Robot Jog Local RY -&quot;">​</a></h4><p>Moves in the negative RY direction in the Local coordinate system.</p><h4 id="_1-120-r-robot-jog-local-rz" tabindex="-1">1.120 R=Robot Jog Local RZ + <a class="header-anchor" href="#_1-120-r-robot-jog-local-rz" aria-label="Permalink to &quot;1.120 R=Robot Jog Local RZ +&quot;">​</a></h4><p>Moves in the positive RZ direction in the Local coordinate system.</p><h4 id="_1-121-r-robot-jog-local-rz" tabindex="-1">1.121 R=Robot Jog Local RZ - <a class="header-anchor" href="#_1-121-r-robot-jog-local-rz" aria-label="Permalink to &quot;1.121 R=Robot Jog Local RZ -&quot;">​</a></h4><p>Moves in the negative RZ direction in the Local coordinate system.</p><h4 id="_1-122-r-stop-program-speed-0" tabindex="-1">1.122 R=Stop Program &amp; Speed 0% <a class="header-anchor" href="#_1-122-r-stop-program-speed-0" aria-label="Permalink to &quot;1.122 R=Stop Program &amp; Speed 0%&quot;">​</a></h4><p>Stops the program and sets the speed to 0%.</p><h3 id="_2-control-box-digital-output-function-definition" tabindex="-1">2. Control Box Digital Output Function Definition <a class="header-anchor" href="#_2-control-box-digital-output-function-definition" aria-label="Permalink to &quot;2. Control Box Digital Output Function Definition&quot;">​</a></h3><br><h4 id="_2-1-h-program-run-l-idle" tabindex="-1">2.1 H=Program Run / L=Idle <a class="header-anchor" href="#_2-1-h-program-run-l-idle" aria-label="Permalink to &quot;2.1 H=Program Run / L=Idle&quot;">​</a></h4><p>H=Running a program or executing an action command<br> L=Idle Situation</p><h4 id="_2-2-l-program-run-h-idle" tabindex="-1">2.2 L=Program Run / H=Idle <a class="header-anchor" href="#_2-2-l-program-run-h-idle" aria-label="Permalink to &quot;2.2 L=Program Run / H=Idle&quot;">​</a></h4><p>L=Running a program or executing an action command<br> H=Idle Situation</p><h4 id="_2-3-h-collision-detected" tabindex="-1">2.3 H=Collision Detected <a class="header-anchor" href="#_2-3-h-collision-detected" aria-label="Permalink to &quot;2.3 H=Collision Detected&quot;">​</a></h4><p>Indicates whether an out-collision or self-collision has been detected.<br> (High State)</p><h4 id="_2-4-h-direct-teaching-mode" tabindex="-1">2.4 H=Direct Teaching mode <a class="header-anchor" href="#_2-4-h-direct-teaching-mode" aria-label="Permalink to &quot;2.4 H=Direct Teaching mode&quot;">​</a></h4><p>Indicates that direct instruction mode is running.<br> (High State)</p><h4 id="_2-5-bypass-din" tabindex="-1">2.5 Bypass Din <a class="header-anchor" href="#_2-5-bypass-din" aria-label="Permalink to &quot;2.5 Bypass Din&quot;">​</a></h4><p>Passes digital input signals of the same number as the selected port.</p><h4 id="_2-6-bypass-tool-din-0" tabindex="-1">2.6 Bypass Tool Din 0 <a class="header-anchor" href="#_2-6-bypass-tool-din-0" aria-label="Permalink to &quot;2.6 Bypass Tool Din 0&quot;">​</a></h4><p>Passes tool flange input port 0 signal.</p><h4 id="_2-7-bypass-tool-din-1" tabindex="-1">2.7 Bypass Tool Din 1 <a class="header-anchor" href="#_2-7-bypass-tool-din-1" aria-label="Permalink to &quot;2.7 Bypass Tool Din 1&quot;">​</a></h4><p>Passes tool flange input port 1 signal.</p><h4 id="_2-8-h-robot-ready-l-not-init" tabindex="-1">2.8 H=Robot Ready / L=Not Init. <a class="header-anchor" href="#_2-8-h-robot-ready-l-not-init" aria-label="Permalink to &quot;2.8 H=Robot Ready / L=Not Init.&quot;">​</a></h4><p>H=Robot Arm Activation Status<br> L=Robot Arm Disabled</p><h4 id="_2-9-h-real-mode-l-simulation" tabindex="-1">2.9 H=Real mode / L=Simulation <a class="header-anchor" href="#_2-9-h-real-mode-l-simulation" aria-label="Permalink to &quot;2.9 H=Real mode / L=Simulation&quot;">​</a></h4><p>H=Real Robot Mode Status<br> L=Simulation Mode Status</p><h4 id="_2-10-h-robot-moving-l-idle" tabindex="-1">2.10 H=Robot Moving / L=Idle <a class="header-anchor" href="#_2-10-h-robot-moving-l-idle" aria-label="Permalink to &quot;2.10 H=Robot Moving / L=Idle&quot;">​</a></h4><p>H=When the robot&#39;s arm is moving<br> L=When the robot arm is stationary</p><h4 id="_2-11-l-robot-moving-h-idle" tabindex="-1">2.11 L=Robot Moving / H=Idle <a class="header-anchor" href="#_2-11-l-robot-moving-h-idle" aria-label="Permalink to &quot;2.11 L=Robot Moving / H=Idle&quot;">​</a></h4><p>L=When the robot&#39;s arm is moving<br> H=When the robot arm is stationary</p><h4 id="_2-12-h-robot-initialize-fail" tabindex="-1">2.12 H=Robot Initialize Fail <a class="header-anchor" href="#_2-12-h-robot-initialize-fail" aria-label="Permalink to &quot;2.12 H=Robot Initialize Fail&quot;">​</a></h4><p>When the robot fails during the activation process<br> (High State)</p><h4 id="_2-13-h-robot-power-on-l-off" tabindex="-1">2.13 H=Robot Power On / L=Off <a class="header-anchor" href="#_2-13-h-robot-power-on-l-off" aria-label="Permalink to &quot;2.13 H=Robot Power On / L=Off&quot;">​</a></h4><p>H=DC power applied to robot arm<br> L=Power-off Status</p><h4 id="_2-14-h-coll-detection-on-l-off" tabindex="-1">2.14 H=Coll. Detection On / L=Off <a class="header-anchor" href="#_2-14-h-coll-detection-on-l-off" aria-label="Permalink to &quot;2.14 H=Coll. Detection On / L=Off&quot;">​</a></h4><p>H=External collision detection mode on<br> L=External collision detection mode off</p><h4 id="_2-15-h-pause-state" tabindex="-1">2.15 H=Pause state <a class="header-anchor" href="#_2-15-h-pause-state" aria-label="Permalink to &quot;2.15 H=Pause state&quot;">​</a></h4><p>Indicates that the program and operation are paused.<br> (High State)</p><h4 id="_2-16-h-inbox-0-trap-flag-on" tabindex="-1">2.16 H=Inbox 0 Trap Flag On <a class="header-anchor" href="#_2-16-h-inbox-0-trap-flag-on" aria-label="Permalink to &quot;2.16 H=Inbox 0 Trap Flag On&quot;">​</a></h4><p>Indicates the status of the trap at in-box 0.<br> (High State)</p><h4 id="_2-17-h-inbox-1-trap-flag-on" tabindex="-1">2.17 H=Inbox 1 Trap Flag On <a class="header-anchor" href="#_2-17-h-inbox-1-trap-flag-on" aria-label="Permalink to &quot;2.17 H=Inbox 1 Trap Flag On&quot;">​</a></h4><p>Indicates the status of the trap at in-box 1.<br> (High State)</p><h4 id="_2-18-pwm-module" tabindex="-1">2.18 PWM Module <a class="header-anchor" href="#_2-18-pwm-module" aria-label="Permalink to &quot;2.18 PWM Module&quot;">​</a></h4><p>Use the port as a PWM module.</p><h4 id="_2-19-h-tpu-is-conndected" tabindex="-1">2.19 H=TPU is conndected <a class="header-anchor" href="#_2-19-h-tpu-is-conndected" aria-label="Permalink to &quot;2.19 H=TPU is conndected&quot;">​</a></h4><p>Indicates that the Teaching Pendant (Ui) is connected.<br> (High State)</p><h4 id="_2-20-h-run-in-make-page" tabindex="-1">2.20 H=Run in MAKE page <a class="header-anchor" href="#_2-20-h-run-in-make-page" aria-label="Permalink to &quot;2.20 H=Run in MAKE page&quot;">​</a></h4><p>Indicates that the program is currently running in the MAKE window.<br> (High State)</p><h4 id="_2-21-h-run-in-play-page" tabindex="-1">2.21 H=Run in PLAY page <a class="header-anchor" href="#_2-21-h-run-in-play-page" aria-label="Permalink to &quot;2.21 H=Run in PLAY page&quot;">​</a></h4><p>Indicates that the program is currently running in the PLAY window.<br> (High State)</p><h4 id="_2-22-h-is-conveyor-mode" tabindex="-1">2.22 H=Is Conveyor mode <a class="header-anchor" href="#_2-22-h-is-conveyor-mode" aria-label="Permalink to &quot;2.22 H=Is Conveyor mode&quot;">​</a></h4><p>Indicates that conveyor mode is in use.<br> (High State)</p><h4 id="_2-23-h-control-box-boot" tabindex="-1">2.23 H=Control Box Boot <a class="header-anchor" href="#_2-23-h-control-box-boot" aria-label="Permalink to &quot;2.23 H=Control Box Boot&quot;">​</a></h4><p>Indicates the controller box boot-complete status.<br> (High State)</p><h4 id="_2-24-h-force-control-mode" tabindex="-1">2.24 H=Force Control mode <a class="header-anchor" href="#_2-24-h-force-control-mode" aria-label="Permalink to &quot;2.24 H=Force Control mode&quot;">​</a></h4><p>Indicates that force control mode is in use.<br> (High State)</p><h4 id="_2-25-pc-alive-pulse" tabindex="-1">2.25 PC Alive Pulse <a class="header-anchor" href="#_2-25-pc-alive-pulse" aria-label="Permalink to &quot;2.25 PC Alive Pulse&quot;">​</a></h4><p>A pulse signal (Alive signal) 0.5 Hz to confirm that the main PC in the control box is alive.</p><h4 id="_2-26-h-speed-bar-100" tabindex="-1">2.26 H=Speed Bar 100% <a class="header-anchor" href="#_2-26-h-speed-bar-100" aria-label="Permalink to &quot;2.26 H=Speed Bar 100%&quot;">​</a></h4><p>Indicates that the speed control bar is 100%.<br> (High State)</p><h4 id="_2-27-h-last-program-load-success" tabindex="-1">2.27 H=Last Program Load Success <a class="header-anchor" href="#_2-27-h-last-program-load-success" aria-label="Permalink to &quot;2.27 H=Last Program Load Success&quot;">​</a></h4><p>Indicates that the last run of &#39;Load a program&#39; was successful.<br> If there is a grammatical error in the written program, the load fails.<br> (High State)</p><h4 id="_2-28-h-tcp-is-in-inbox-0" tabindex="-1">2.28 H=TCP is in Inbox 0 <a class="header-anchor" href="#_2-28-h-tcp-is-in-inbox-0" aria-label="Permalink to &quot;2.28 H=TCP is in Inbox 0&quot;">​</a></h4><p>Indicates that TCP has entered the in-box area 0.<br> (High State)</p><h4 id="_2-29-h-tcp-is-in-inbox-1" tabindex="-1">2.29 H=TCP is in Inbox 1 <a class="header-anchor" href="#_2-29-h-tcp-is-in-inbox-1" aria-label="Permalink to &quot;2.29 H=TCP is in Inbox 1&quot;">​</a></h4><p>Indicates that TCP has entered the in-box area 1.<br> (High State)</p><h4 id="_2-30-h-is-alarm" tabindex="-1">2.30 H=Is Alarm <a class="header-anchor" href="#_2-30-h-is-alarm" aria-label="Permalink to &quot;2.30 H=Is Alarm&quot;">​</a></h4><p>Indicates that the alarm function on the program has been turned on and program is paused.<br> (High State)</p><h4 id="_2-31-h-robot-posture-is-begin-posture" tabindex="-1">2.31 H=Robot posture is Begin posture <a class="header-anchor" href="#_2-31-h-robot-posture-is-begin-posture" aria-label="Permalink to &quot;2.31 H=Robot posture is Begin posture&quot;">​</a></h4><p>Indicates that the robot arm is currently in the start position (home position).<br> The starting position (home position) is defined based on the currently loaded program.<br> (High State)</p><h4 id="_2-32-h-emergency-teaching-enable" tabindex="-1">2.32 H=Emergency Teaching Enable <a class="header-anchor" href="#_2-32-h-emergency-teaching-enable" aria-label="Permalink to &quot;2.32 H=Emergency Teaching Enable&quot;">​</a></h4><p>Indicates that emergency direct teaching mode is enabled.<br> (High State)</p><h4 id="_2-33-h-prog-run-in-sub-p-area" tabindex="-1">2.33 H=Prog. Run in Sub.P area <a class="header-anchor" href="#_2-33-h-prog-run-in-sub-p-area" aria-label="Permalink to &quot;2.33 H=Prog. Run in Sub.P area&quot;">​</a></h4><p>When the currently running program section is a sub-program (Sub.P ), High signal is output.<br> (High State)</p><h4 id="_2-34-h-normal-program-run-l-others" tabindex="-1">2.34 H=Normal Program Run / L=Others <a class="header-anchor" href="#_2-34-h-normal-program-run-l-others" aria-label="Permalink to &quot;2.34 H=Normal Program Run / L=Others&quot;">​</a></h4><p>H=Normal program play status / L=Other cases<br> (A case that is not a pause due to pause or external collision detection is defined as &#39;normal&#39;)<br> (High State)</p><h4 id="_2-35-l-normal-program-run-h-others" tabindex="-1">2.35 L=Normal Program Run / H=Others <a class="header-anchor" href="#_2-35-l-normal-program-run-h-others" aria-label="Permalink to &quot;2.35 L=Normal Program Run / H=Others&quot;">​</a></h4><p>L=Normal program play status / H=Other cases<br> (A case that is not a pause due to pause or external collision detection is defined as &#39;normal&#39;)<br> (Low State)</p><h4 id="_2-36-h-hand-controller-f1-pressed" tabindex="-1">2.36 H=Hand Controller F1 pressed <a class="header-anchor" href="#_2-36-h-hand-controller-f1-pressed" aria-label="Permalink to &quot;2.36 H=Hand Controller F1 pressed&quot;">​</a></h4><p>Indicates that the F1 button on the hand controller is pressed.</p><h4 id="_2-37-h-hand-controller-f2-pressed" tabindex="-1">2.37 H=Hand Controller F2 pressed <a class="header-anchor" href="#_2-37-h-hand-controller-f2-pressed" aria-label="Permalink to &quot;2.37 H=Hand Controller F2 pressed&quot;">​</a></h4><p>Indicates that the F2 button on the hand controller is pressed.</p><h4 id="_2-38-h-hand-controller-f3-pressed" tabindex="-1">2.38 H=Hand Controller F3 pressed <a class="header-anchor" href="#_2-38-h-hand-controller-f3-pressed" aria-label="Permalink to &quot;2.38 H=Hand Controller F3 pressed&quot;">​</a></h4><p>Indicates that the F3 button on the hand controller is pressed.</p><h4 id="_2-39-h-hand-controller-f4-pressed" tabindex="-1">2.39 H=Hand Controller F4 pressed <a class="header-anchor" href="#_2-39-h-hand-controller-f4-pressed" aria-label="Permalink to &quot;2.39 H=Hand Controller F4 pressed&quot;">​</a></h4><p>Indicates that the F4 button on the hand controller is pressed.</p><h4 id="_2-40-l-tcp-is-in-inbox-0" tabindex="-1">2.40 L=TCP is in Inbox 0 <a class="header-anchor" href="#_2-40-l-tcp-is-in-inbox-0" aria-label="Permalink to &quot;2.40 L=TCP is in Inbox 0&quot;">​</a></h4><p>Indicates that TCP has entered the in-box area 0.<br> (Low State)</p><h4 id="_2-41-l-tcp-is-in-inbox-1" tabindex="-1">2.41 L=TCP is in Inbox 1 <a class="header-anchor" href="#_2-41-l-tcp-is-in-inbox-1" aria-label="Permalink to &quot;2.41 L=TCP is in Inbox 1&quot;">​</a></h4><p>Indicates that TCP has entered the in-box area 1.<br> (Low State)</p><h4 id="_2-42-sync-with-dout-0-15" tabindex="-1">2.42 Sync with Dout 0~15 <a class="header-anchor" href="#_2-42-sync-with-dout-0-15" aria-label="Permalink to &quot;2.42 Sync with Dout 0~15&quot;">​</a></h4><p>Indicates the signal in synchronization with the signal from 0 to 15.</p><h4 id="_2-43-h-is-sos-state" tabindex="-1">2.43 H=Is SOS State <a class="header-anchor" href="#_2-43-h-is-sos-state" aria-label="Permalink to &quot;2.43 H=Is SOS State&quot;">​</a></h4><p>Indicates the SOS status.<br> (High state)</p><h4 id="_2-44-l-is-sos-state" tabindex="-1">2.44 L=Is SOS State <a class="header-anchor" href="#_2-44-l-is-sos-state" aria-label="Permalink to &quot;2.44 L=Is SOS State&quot;">​</a></h4><p>Indicates the SOS status.<br> (Low state)</p><h4 id="_2-45-h-emg-button-released-l-pressed" tabindex="-1">2.45 H=EMG Button Released / L=Pressed <a class="header-anchor" href="#_2-45-h-emg-button-released-l-pressed" aria-label="Permalink to &quot;2.45 H=EMG Button Released / L=Pressed&quot;">​</a></h4><p>Outputs High when the emergency switch is released.</p><h4 id="_2-46-l-emg-button-released-h-pressed" tabindex="-1">2.46 L=EMG Button Released / H=Pressed <a class="header-anchor" href="#_2-46-l-emg-button-released-h-pressed" aria-label="Permalink to &quot;2.46 L=EMG Button Released / H=Pressed&quot;">​</a></h4><p>Outputs Low when the emergency switch is released.</p><h4 id="_2-47-l-robot-speed-under-250mm-s" tabindex="-1">2.47 L=Robot Speed under 250mm/s <a class="header-anchor" href="#_2-47-l-robot-speed-under-250mm-s" aria-label="Permalink to &quot;2.47 L=Robot Speed under 250mm/s&quot;">​</a></h4><p>Outputs Low when the robot arm speed is below 250 mm/s.</p><h4 id="_2-48-h-robot-speed-under-250mm-s" tabindex="-1">2.48 H=Robot Speed under 250mm/s <a class="header-anchor" href="#_2-48-h-robot-speed-under-250mm-s" aria-label="Permalink to &quot;2.48 H=Robot Speed under 250mm/s&quot;">​</a></h4><p>Outputs High when the robot arm speed is below 250 mm/s.</p><h4 id="_2-49-h-near-joint-limit" tabindex="-1">2.49 H=Near Joint Limit <a class="header-anchor" href="#_2-49-h-near-joint-limit" aria-label="Permalink to &quot;2.49 H=Near Joint Limit&quot;">​</a></h4><p>Outputs High when the robot arm reaches a singularity.</p><h4 id="_2-50-h-robot-arm-under-activationg" tabindex="-1">2.50 H=Robot Arm under Activationg <a class="header-anchor" href="#_2-50-h-robot-arm-under-activationg" aria-label="Permalink to &quot;2.50 H=Robot Arm under Activationg&quot;">​</a></h4><p>Outputs High when the robot arm power is being supplied.</p><h4 id="_2-51-h-under-program-loading" tabindex="-1">2.51 H=Under program Loading <a class="header-anchor" href="#_2-51-h-under-program-loading" aria-label="Permalink to &quot;2.51 H=Under program Loading&quot;">​</a></h4><p>Indicates the program loading state.</p><h4 id="_2-52-h-teleoperation-master" tabindex="-1">2.52 H=TeleOperation Master <a class="header-anchor" href="#_2-52-h-teleoperation-master" aria-label="Permalink to &quot;2.52 H=TeleOperation Master&quot;">​</a></h4><p>Indicates TeleOperation Master state.</p><h4 id="_2-53-h-teleoperation-slave" tabindex="-1">2.53 H=TeleOperation Slave <a class="header-anchor" href="#_2-53-h-teleoperation-slave" aria-label="Permalink to &quot;2.53 H=TeleOperation Slave&quot;">​</a></h4><p>Indicates TeleOperation Slave state.</p><h4 id="_2-54-h-servo-mode-idle" tabindex="-1">2.54 H=Servo Mode &amp; Idle <a class="header-anchor" href="#_2-54-h-servo-mode-idle" aria-label="Permalink to &quot;2.54 H=Servo Mode &amp; Idle&quot;">​</a></h4><p>Indicates Servo Mode (Idle state).</p><h4 id="_2-55-h-safety-ems2-pressed" tabindex="-1">2.55 H=Safety EMS2 Pressed <a class="header-anchor" href="#_2-55-h-safety-ems2-pressed" aria-label="Permalink to &quot;2.55 H=Safety EMS2 Pressed&quot;">​</a></h4><p>Outputs High when the EMS2 wiring is not in a shorted state.</p><h4 id="_2-56-h-safety-prs-pressed" tabindex="-1">2.56 H=Safety PRS Pressed <a class="header-anchor" href="#_2-56-h-safety-prs-pressed" aria-label="Permalink to &quot;2.56 H=Safety PRS Pressed&quot;">​</a></h4><p>Outputs High when the PRS wiring is not in a shorted state.</p><h4 id="_2-57-h-safety-hss-pressed" tabindex="-1">2.57 H=Safety HSS Pressed <a class="header-anchor" href="#_2-57-h-safety-hss-pressed" aria-label="Permalink to &quot;2.57 H=Safety HSS Pressed&quot;">​</a></h4><p>Outputs High when the HSS wiring is not in a shorted state.</p><h4 id="_2-58-h-safety-sss-pressed" tabindex="-1">2.58 H=Safety SSS Pressed <a class="header-anchor" href="#_2-58-h-safety-sss-pressed" aria-label="Permalink to &quot;2.58 H=Safety SSS Pressed&quot;">​</a></h4><p>Outputs High when the SSS wiring is not in a shorted state.</p>',365),n=[i];function s(l,h,d,p,c,u){return o(),a("div",null,n)}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
